163	  /**
164	   * Is the given input list.
165	   * <ul>
166	   *   <li>already sorted by offset</li>
167	   *   <li>each range is more than minimumSeek apart</li>
168	   *   <li>the start and end of each range is a multiple of chunkSize</li>
169	   * </ul>
170	   *
171	   * @param input the list of input ranges.
172	   * @param chunkSize the size of the chunks that the offset and end must align to.
173	   * @param minimumSeek the minimum distance between ranges.
174	   * @return true if we can use the input list as is.
175	   */
176	  public static boolean isOrderedDisjoint(List<? extends FileRange> input,
177	                                          int chunkSize,
178	                                          int minimumSeek) {
179	    long previous = -minimumSeek;
180	    for (FileRange range: input) {
181	      long offset = range.getOffset();
182	      long end = range.getOffset() + range.getLength();
183	      if (offset % chunkSize != 0 ||
184	              end % chunkSize != 0 ||
185	              (offset - previous < minimumSeek)) {
186	        return false;
187	      }
188	      previous = end;
189	    }
190	    return true;
191	  }
192	
193	  /**
194	   * Calculates floor value of offset based on chunk size.
195	   * @param offset file offset.
196	   * @param chunkSize file chunk size.
197	   * @return  floor value.
198	   */
199	  public static long roundDown(long offset, int chunkSize) {
200	    if (chunkSize > 1) {
201	      return offset - (offset % chunkSize);
202	    } else {
203	      return offset;
204	    }
205	  }
