320	                             IntFunction<ByteBuffer> allocate) throws IOException {
321	
322	      List<? extends FileRange> sortedRanges = Arrays.asList(sortRanges(ranges));
323	      // Set up all of the futures, so that we can use them if things fail
324	      for(FileRange range: sortedRanges) {
